class NonMaturityDepositStabilityRequest(BaseModel):
    """Request parameters for non_maturity_deposit_stability()."""

    model_config = ConfigDict(allow_inf_nan=False)

    balance_history: list[float] | list[list[float]] = Field(
        description="Historical deposit balances (>= 2 observations)."
    )
    confidence_level: float = Field(
        default=0.99, description="Confidence for the stable floor in [0.5, 1)."
    )

    @field_validator("confidence_level")
    @classmethod
    def _confidence_range(cls, v: float) -> float:
        if v is not None and not (0.90 <= v <= 0.9999):
            raise ValueError(f"confidence_level {v} outside regulatory range [0.90, 0.9999]")
        return v


